/**
 * The placement table (where every E2E spec runs), rendered from apps/web/e2e/test-utils/placement.ts:
 *
 *   node --experimental-strip-types --no-warnings scripts/e2e/placement-doc.ts            # print it
 *   node --experimental-strip-types --no-warnings scripts/e2e/placement-doc.ts --out f.md # write it
 *
 * Not committed (a generated file conflicted on nearly every PR): the Local E2E build job puts it
 * in its job summary, and placement.ts is the source of truth, guarded by
 * scripts/qa/__tests__/e2e-placement.test.ts.
 */
import { writeFileSync } from 'node:fs';
import { SPEC_PLACEMENT, type Placement } from '../../apps/web/e2e/test-utils/placement.ts';


/** Suite of a spec path: which Playwright config runs it today. */
export function suiteOf(path: string): string {
  if (path.startsWith('apps/admin-web/')) return 'admin';
  if (path.includes('/e2e/release-prod/')) return 'release-prod';
  if (path.includes('/e2e/release/')) return 'release';
  if (path.includes('/e2e/themes/')) return 'themes';
  if (path.includes('/e2e/player/')) return 'player';
  return 'web';
}

const SUITE_CONFIG: Record<string, string> = {
  web: 'apps/web/playwright.config.ts (e2e-tests.yml)',
  release: 'apps/web/playwright.release.config.ts (release-e2e.yml, release.yml)',
  admin: 'apps/admin-web/playwright.config.ts (admin-e2e.yml)',
  themes: 'apps/web/playwright.themes.config.ts (theme-visibility.yml)',
  player: 'apps/web/playwright.player.config.ts (player-e2e.yml)',
  'release-prod': 'apps/web/playwright.release-prod.config.ts (prod-signed-in.yml)',
};
const SUITES = Object.keys(SUITE_CONFIG);

export function renderPlacementDoc(): string {
  const paths = Object.keys(SPEC_PLACEMENT).sort();
  const count = (suite: string | null, placement: Placement) =>
    paths.filter((p) => (suite === null || suiteOf(p) === suite) && SPEC_PLACEMENT[p].placement === placement).length;
  const lines: string[] = [
    '# Where each E2E spec runs',
    '',
    '<!-- Generated by scripts/e2e/placement-doc.ts from apps/web/e2e/test-utils/placement.ts. -->',
    '',
    'Every spec file is **local** or **deployed**.',
    '',
    '- **local**: UI behaviour and our own API logic. It runs against a local stack that each CI job boots for itself:',
    '  web, admin-web, api-videos, admin-api, processor and websocket-server under wrangler/miniflare with local D1, R2,',
    '  KV and queues, deterministic seed fixtures, a fake Bunny (upload accepted, "encoded" on demand, fixture HLS) and',
    '  mocked AI providers. Sign-in is real: the Auth repo (issuer, profile app, auth admin) runs locally with local D1/KV,',
    '  clients seeded with localhost redirect URIs and the E2E code sink. The CMS and www run locally too where a spec',
    '  crosses into them. Auth, CMS and www are checked out at the ref each last released. Specs that are not about',
    '  auth may mint a session as a fast path. No shared QA data, so jobs run fully in parallel and shard.',
    '- **deployed**: needs real infrastructure, so it runs against QA and stage and is the release gate. The reason',
    '  starts with the category: `sso` (sessions on the real `.alummahnow.net` cookie domain: `Domain=`, `Secure`,',
    '  HTTPS; on localhost every app shares one host\'s cookies, so this cannot be reproduced), `bunny` (real upload and encode),',
    '  `media` (real CDN/R2 playback), `pipeline` (queues and processor end to end under load) or `shared-env`',
    '  (deployed-environment checks).',
    '',
    'Deploy skew and migrations are checked outside the E2E suites, by the release itself: `scripts/release/skew-check.ts`',
    'after every promote, `pnpm check:migrations` and `pnpm check:schema` on every PR. `deploy-skew.spec.ts` simulates a',
    'new build with route interception, so it is local.',
    '',
    '`@load` marks files with load or timing tests. Those never gate (`E2E_LOAD=only`, non-blocking), wherever they run.',
    '',
    '## Data',
    '',
    'Every spec file creates the data it needs in its own setup and removes it afterwards, on the local stack and',
    'on QA/stage alike: `apps/web/e2e/release/builders.ts` (`useOwnData(test)` → `createUser`, `grantCreator`,',
    '`createChannel`, `createVideo` (fake-Bunny encode locally, the real encode on QA/stage, a slow one skips with',
    '#929), `createPlaylist`, `createPost`, `createComment`, `cleanup()`). Names carry the run id, spec file and',
    'worker, so parallel shards never share rows. No spec reads the global seed, theme-demo videos, "the newest',
    'public video", hard-coded ids (`E2E_PLAYBACK_VIDEO_ID`, `443418c1`) or other runs\' leftovers;',
    '`scripts/qa/__tests__/own-data.test.ts` enforces it (files still to move are listed there, and the list only',
    'shrinks). The global seed keeps only what cannot be made per test: admin and role bootstrap, and the',
    'creator-tier definitions.',
    '',
    'Until a batch is moved, every spec still runs where it runs today; the local jobs replace the QA runs batch by batch.',
    '',
    '## Counts',
    '',
    '| Suite | Config | Local | Deployed |',
    '|---|---|---:|---:|',
    ...SUITES.map((s) => `| ${s} | \`${SUITE_CONFIG[s].replace(' (', '` (')} | ${count(s, 'local')} | ${count(s, 'deployed')} |`),
    `| **all** | | **${count(null, 'local')}** | **${count(null, 'deployed')}** |`,
    '',
  ];
  for (const placement of ['deployed', 'local'] as const) {
    lines.push(`## ${placement === 'deployed' ? 'Deployed (QA and stage)' : 'Local stack'}`, '');
    for (const suite of SUITES) {
      const rows = paths.filter((p) => suiteOf(p) === suite && SPEC_PLACEMENT[p].placement === placement);
      if (rows.length === 0) continue;
      lines.push(`### ${suite}`, '', '| Spec | Reason | @load |', '|---|---|:---:|');
      for (const p of rows) {
        const { reason, load } = SPEC_PLACEMENT[p];
        lines.push(`| \`${p.replace(/^apps\/(web|admin-web)\/e2e\//, '')}\` | ${reason.replace(/\\/g, '\\\\').replace(/\|/g, '\\|')} | ${load ? 'yes' : ''} |`);
      }
      lines.push('');
    }
  }
  return lines.join('\n');
}

if (import.meta.main) {
  const doc = renderPlacementDoc();
  const at = process.argv.indexOf('--out');
  if (at >= 0 && process.argv[at + 1]) writeFileSync(process.argv[at + 1], doc);
  else process.stdout.write(doc);
}
